<template><SurfaceCard aria-labelledby="content-history-title"><h2 id="content-history-title">{{ t('publicContentAdmin.history') }}</h2><p v-if="!items.length">{{ t('publicContentAdmin.emptyHistory') }}</p><ol v-else class="history"><li v-for="item in items" :key="item.guid"><div><strong>v{{ item.version }}</strong> · {{ item.reason==='restore'?t('publicContentAdmin.restored'):t('publicContentAdmin.published') }}<br><small>{{ item.createdAt }} · {{ t('publicContentAdmin.sourceRevision',{revision:item.sourceRevision}) }}</small></div><button type="button" :disabled="busy||restoreDisabled" @click="$emit('restore',item,$event)">{{ t('publicContentAdmin.restore') }}</button></li></ol><button v-if="items.length<total" type="button" :disabled="busy" @click="$emit('more')">{{ t('publicContentAdmin.more') }}</button></SurfaceCard></template>
<script setup>import SurfaceCard from '@/components/shell/SurfaceCard.vue';import { useI18n } from '@/composables/useI18n';defineProps({items:{type:Array,default:()=>[]},total:{type:Number,default:0},busy:Boolean,restoreDisabled:Boolean});defineEmits(['restore','more']);const{t}=useI18n()</script>
<style scoped>.history{display:grid;gap:10px;padding:0;list-style:none}.history li{display:flex;justify-content:space-between;gap:16px;padding:12px;border:1px solid var(--el-border-color);border-radius:8px}.history button{min-height:44px}@media(max-width:600px){.history li{align-items:stretch;flex-direction:column}}</style>
